from copy import deepcopy


def _validate_rows(rows):
    if type(rows) is not list:
        raise TypeError("rows must be a list")
    if any(type(row) is not dict for row in rows):
        raise TypeError("each row must be a dictionary")


def upgrade_rows(rows):
    _validate_rows(rows)
    if any("unique_id" in row for row in rows):
        raise ValueError("row already has unique_id")
    result = list(rows)
    for index, row in enumerate(result):
        encoded = format(index, "031x")
        if len(encoded) != 31:
            raise ValueError("too many rows to encode")
        row["unique_id"] = "I" + encoded
    return result


def downgrade_rows(rows):
    _validate_rows(rows)
    result = deepcopy(rows)
    for row in result:
        row.pop("unique_id", None)
    return result

